import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtemp, readFile} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {createHash} from 'node:crypto';
import {openAgentStore} from '../packages/agent/store.mjs';

// Generated by the frozen alpha.7 implementation (tgz SHA 0199b719...31c80c3).
// Only journal.jsonl is deterministic here. PID/nonce/root/lock files are excluded.
const golden = {
  v1: {sha256: '85967bea0289db918fb2c096b5ceef30bce80f6e95e1d08e92470c64023a6da8', sequence: 9, bytes: 2925},
  v2: {sha256: '10b4bda7f73e9fffdebbdc958236aab2c8b8bf12846e5780355ef2bf8e36de45', sequence: 5, bytes: 1572},
  appended: {sha256: 'aa849679832d5259988761ffd128dbfaff4f43767ad951e3f352d4b781e8c6cf', sequence: 7, bytes: 2168},
};

test('state refactor retains frozen alpha7 journal bytes through v1 checkpoint and v2 append', async t => {
  const root = await mkdtemp(join(tmpdir(), 'aqa-state-refactor-'));
  const agentId = 'refactor-golden';
  let store = await openAgentStore(root, {agentId, instanceId: 'fixed-instance', maxEntries: 128});
  t.after(() => store.close());
  const input = {phase: 'received', cleanupState: 'unknown', fence: 1};
  await store.set('lease:one', input);
  input.phase = 'mutated';
  assert.equal(store.get('lease:one').phase, 'received');
  await store.set('lease:one', {phase: 'executing', cleanupState: 'unknown', fence: 1});
  await store.set('historical:pending', {ack: false, reference: {sha256: 'immutable'}});
  await store.enqueue('one', {event: {sequence: 1, type: 'run.started'}});
  await store.enqueue('one', {event: {sequence: 2, type: 'step.started'}});
  await store.ack('one', 1);
  const body = {agentId, claimRequestId: 'empty'};
  await store.set('claim:empty', {body, phase: 'requested'});
  await store.set('claim:empty', {body, phase: 'empty', leaseId: null});
  await store.set('receipt:closed', {receipt: 'fixed', cleanupState: 'confirmed'});

  async function verifyBytes(expected) {
    const bytes = await readFile(join(root, 'journal.jsonl'));
    assert.equal(createHash('sha256').update(bytes).digest('hex'), expected.sha256);
    assert.equal(bytes.length, expected.bytes);
    assert.equal(store.status().bytes, expected.bytes);
    assert.equal(store.status().sequence, expected.sequence);
  }
  await verifyBytes(golden.v1);
  assert.equal(store.status().journalVersion, 1);
  assert.equal(await store.compactEmptyClaims({force: true}), true);
  await verifyBytes(golden.v2);
  assert.equal(store.status().journalVersion, 2);
  assert.equal(store.get('claim:empty'), undefined);
  assert.equal(store.get('lease:one').cleanupState, 'unknown');
  assert.equal(store.get('historical:pending').ack, false);
  assert.equal(store.get('receipt:closed').receipt, 'fixed');
  assert(Object.isFrozen(store.entries()));
  assert(Object.isFrozen(store.get('historical:pending').reference));
  assert(Object.isFrozen(store.pending('one')[0].payload.event));
  await store.close();

  store = await openAgentStore(root, {agentId, instanceId: 'fixed-reopened', maxEntries: 128});
  assert.equal(await store.enqueue('one', {event: {sequence: 3, type: 'step.finished'}}), 3);
  await store.ack('one', 2);
  await verifyBytes(golden.appended);
  assert.equal(store.acknowledged('one'), 2);
  assert.deepEqual(store.pending('one'), [{sequence: 3, payload: {event: {sequence: 3, type: 'step.finished'}}}]);
  assert.equal(store.status().lifetimeBounded, true);
});

test('replacement publishes checkpoint state only after reopen and serializes queued writes', async t => {
  const root = await mkdtemp(join(tmpdir(), 'aqa-state-publish-'));
  let reached;
  const atReplacement = new Promise(resolve => { reached = resolve; });
  let resume;
  const permission = new Promise(resolve => { resume = resolve; });
  const store = await openAgentStore(root, {
    agentId: 'publication',
    checkpointHook: async phase => {
      if (phase === 'after-replace') {
        reached();
        await permission;
      }
    },
  });
  t.after(async () => { resume(); await store.close(); });
  const body = {agentId: 'publication', claimRequestId: 'empty'};
  await store.set('claim:empty', {body, phase: 'requested'});
  await store.set('claim:empty', {body, phase: 'empty', leaseId: null});
  await store.enqueue('scope', {value: 1});
  await store.ack('scope', 1);
  const before = store.status();
  const checkpoint = store.compactEmptyClaims({force: true});
  await atReplacement;
  assert.deepEqual(store.status(), before);
  assert.equal(store.get('claim:empty').phase, 'empty');
  let appended = false;
  const pendingWrite = store.enqueue('scope', {value: 2}).then(value => { appended = true; return value; });
  await new Promise(resolve => setImmediate(resolve));
  assert.equal(appended, false);
  assert.deepEqual(store.pending('scope'), []);
  resume();
  assert.equal(await checkpoint, true);
  assert.equal(await pendingWrite, 2);
  assert.equal(store.get('claim:empty'), undefined);
  assert.equal(store.status().journalVersion, 2);
  assert.equal(store.acknowledged('scope'), 1);
  assert.deepEqual(store.pending('scope'), [{sequence: 2, payload: {value: 2}}]);
});
